# AI Office v2.4 Part B Live Discord Intake Installer
$ErrorActionPreference = "Stop"
$Repository = "E:\AI\AI-Office"
if (-not (Test-Path -LiteralPath $Repository -PathType Container)) { throw "AI Office repository not found at E:\AI\AI-Office" }
Set-Location $Repository
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupDirectory = Join-Path $Repository ("workspace\installer-backups\v2.4-part-b-" + $Timestamp)
New-Item -ItemType Directory -Path $BackupDirectory -Force | Out-Null
foreach ($Directory in @(
 "config\discord-office",
 "workspace\discord-office\state",
 "workspace\templates",
 "scripts\discord-office",
 "docs"
)) { New-Item -ItemType Directory -Path (Join-Path $Repository $Directory) -Force | Out-Null }
function Write-EmbeddedFile {
 param([string]$RelativePath,[string]$Base64Content)
 $Destination = Join-Path $Repository $RelativePath
 $Parent = Split-Path -Parent $Destination
 if ($Parent -and -not (Test-Path -LiteralPath $Parent)) { New-Item -ItemType Directory -Path $Parent -Force | Out-Null }
 if (Test-Path -LiteralPath $Destination -PathType Leaf) {
   $BackupPath = Join-Path $BackupDirectory $RelativePath
   $BackupParent = Split-Path -Parent $BackupPath
   if ($BackupParent -and -not (Test-Path -LiteralPath $BackupParent)) { New-Item -ItemType Directory -Path $BackupParent -Force | Out-Null }
   Copy-Item -LiteralPath $Destination -Destination $BackupPath -Force
 }
 [IO.File]::WriteAllBytes($Destination,[Convert]::FromBase64String($Base64Content))
 Write-Host "[WRITTEN] $RelativePath" -ForegroundColor Green
}
Write-EmbeddedFile -RelativePath "config\discord-office\live-runtime-policy.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "config\discord-office\discord-connection-schema.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "workspace\templates\discord-connection-template.json" -Base64Content "ewogICJzdGF0dXMiOiAiY29ubmVjdGVkIiwKICAiYm90X3VzZXJfaWQiOiAiIiwKICAiYm90X3VzZXJuYW1lIjogIiIsCiAgImd1aWxkX2NvdW50IjogMCwKICAiY29ubmVjdGVkX2F0IjogIiIsCiAgInVwZGF0ZWRfYXQiOiAiIgp9Cg=="
Write-EmbeddedFile -RelativePath "scripts\discord-office\AIOfficeDiscordRuntime.Common.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\discord-office\Initialize-AIOfficeDiscordConnection.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\discord-office\Set-AIOfficeDiscordAllowlist.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\discord-office\Invoke-AIOfficeDiscordInboundMessage.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\discord-office\Test-AIOfficeDiscordLiveRuntime.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "docs\AI-Office-v2.4-Part-B-Live-Discord-Intake.md" -Base64Content ""
$ScriptPaths = @(
 "E:\AI\AI-Office\scripts\discord-office\AIOfficeDiscordRuntime.Common.ps1",
 "E:\AI\AI-Office\scripts\discord-office\Initialize-AIOfficeDiscordConnection.ps1",
 "E:\AI\AI-Office\scripts\discord-office\Set-AIOfficeDiscordAllowlist.ps1",
 "E:\AI\AI-Office\scripts\discord-office\Invoke-AIOfficeDiscordInboundMessage.ps1",
 "E:\AI\AI-Office\scripts\discord-office\Test-AIOfficeDiscordLiveRuntime.ps1"
)
foreach ($ScriptPath in $ScriptPaths) {
 $Tokens=$null; $ParseErrors=$null
 [System.Management.Automation.Language.Parser]::ParseFile($ScriptPath,[ref]$Tokens,[ref]$ParseErrors) | Out-Null
 if ($ParseErrors.Count -gt 0) { throw ("Syntax error in " + $ScriptPath + ": " + (($ParseErrors | ForEach-Object { $_.Message }) -join "; ")) }
}
Write-Host ""
Write-Host "AI Office v2.4 Part B Live Discord Intake installed successfully." -ForegroundColor Green
Write-Host "Next: configure a Discord bot token and allowlist IDs before live testing." -ForegroundColor Yellow
Write-Host "Backups: $BackupDirectory" -ForegroundColor Cyan